import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Module: trait_inference","description":"","frontmatter":{},"headers":[],"relativePath":"api/host/handl_plugin_ext_refinement/trait_inference.md","filePath":"api/host/handl_plugin_ext_refinement/trait_inference.md"}`),a={name:`api/host/handl_plugin_ext_refinement/trait_inference.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p><strong>handl_plugin_ext_refinement &gt; trait_inference</strong></p><h1 id="module-trait-inference" tabindex="-1">Module: trait_inference <a class="header-anchor" href="#module-trait-inference" aria-label="Permalink to “Module: trait_inference”">​</a></h1><h2 id="contents" tabindex="-1">Contents <a class="header-anchor" href="#contents" aria-label="Permalink to “Contents”">​</a></h2><p><strong>Structs</strong></p><ul><li><a href="#lawannotation"><code>LawAnnotation</code></a> - A law-based contract annotation. When a graph is recognized as satisfying</li></ul><p><strong>Enums</strong></p><ul><li><a href="#law"><code>Law</code></a> - Named equational laws between graph expressions, mirroring the Lean4</li></ul><p><strong>Functions</strong></p><ul><li><a href="#infer-law-annotations"><code>infer_law_annotations</code></a> - Infer law-based contract annotations for a <code>Term</code> graph.</li><li><a href="#inferred-trait"><code>inferred_trait</code></a> - The set of laws inferred from a graph&#39;s wiring, by structural recursion.</li><li><a href="#is-identity-td"><code>is_identity_td</code></a> - Whether a <code>TermData</code> is the identity arrow (<code>op(&quot;id&quot;)</code> with no args).</li><li><a href="#law-strengthening"><code>law_strengthening</code></a> - The contract-strengthening description for a law.</li><li><a href="#law-verified"><code>law_verified</code></a> - Whether a law is verified by CutElim normalization.</li><li><a href="#satisfies-law"><code>satisfies_law</code></a> - Whether a <code>Term</code> graph <code>G</code> satisfies <code>law</code>.</li><li><a href="#uses-first"><code>uses_first</code></a> - Whether a <code>Term</code> graph <em>uses <code>first</code></em> — i.e. <code>Term::First</code> appears</li><li><a href="#uses-first-td"><code>uses_first_td</code></a> - Data-driven counterpart of [<code>uses_first</code>], operating on [<code>TermData</code>].</li><li><a href="#uses-left"><code>uses_left</code></a> - Whether a <code>Term</code> graph <em>uses <code>left</code></em> — i.e. the coproduct-functor</li><li><a href="#uses-left-td"><code>uses_left_td</code></a> - Data-driven counterpart of [<code>uses_left</code>], operating on [<code>TermData</code>].</li></ul><hr><h2 id="handl-plugin-ext-refinement-trait-inference-law" tabindex="-1">handl_plugin_ext_refinement::trait_inference::Law <a class="header-anchor" href="#handl-plugin-ext-refinement-trait-inference-law" aria-label="Permalink to “handl_plugin_ext_refinement::trait_inference::Law”">​</a></h2><p><em>Enum</em></p><p>Named equational laws between graph expressions, mirroring the Lean4 <code>Law</code> inductive type.</p><p>Each constructor identifies a specific law and names the combinator it applies to (<code>first</code> for product-functor laws, <code>left</code> for coproduct-functor laws). The Lean4 formalization carries type/graph parameters; the Rust port names only the law (the parameters are implicit in the <code>Term</code> structure being analyzed).</p><h1 id="the-four-laws" tabindex="-1">The four laws <a class="header-anchor" href="#the-four-laws" aria-label="Permalink to “The four laws”">​</a></h1><ol><li><strong>FunctorIdentity</strong>: <code>first (idG A) ≡ idG (A × D)</code> — functoriality of <code>first</code> preserves the identity.</li><li><strong>FunctorComposition</strong>: <code>first (comp G H) ≡ comp (first G) (first H)</code> — functoriality of <code>first</code> distributes over composition (fusion).</li><li><strong>CoproductIdentity</strong>: <code>left (idG A) ≡ idG (A + D)</code> — functoriality of <code>left</code> preserves the identity.</li><li><strong>CoproductComposition</strong>: <code>left (comp G H) ≡ comp (left G) (left H)</code> — functoriality of <code>left</code> distributes over composition (fusion).</li></ol><p><strong>Variants:</strong></p><ul><li><code>FunctorIdentity</code> - <code>first (idG A) ≡ idG (A × D)</code> — functor identity for <code>first</code>.</li><li><code>FunctorComposition</code> - <code>first (comp G H) ≡ comp (first G) (first H)</code> — functor composition</li><li><code>CoproductIdentity</code> - <code>left (idG A) ≡ idG (A + D)</code> — coproduct functor identity for <code>left</code>.</li><li><code>CoproductComposition</code> - <code>left (comp G H) ≡ comp (left G) (left H)</code> — coproduct functor</li></ul><p><strong>Methods:</strong></p><ul><li><code>fn all() -&gt; &amp;&#39;static [Law]</code> - All four laws, in declaration order.</li><li><code>fn name(self: &amp;Self) -&gt; &amp;&#39;static str</code> - A human-readable name for the law (matching the Lean4 constructor</li><li><code>fn equation(self: &amp;Self) -&gt; &amp;&#39;static str</code> - The equation the law states, in arrow-calculus notation.</li><li><code>fn is_functor_law(self: &amp;Self) -&gt; bool</code> - Whether this law applies to the <code>first</code> (product functor) combinator.</li><li><code>fn is_coproduct_law(self: &amp;Self) -&gt; bool</code> - Whether this law applies to the <code>left</code> (coproduct functor) combinator.</li></ul><p><strong>Traits:</strong> Eq, Copy</p><p><strong>Trait Implementations:</strong></p><ul><li><strong>Debug</strong><ul><li><code>fn fmt(self: &amp;Self, f: &amp; mut $crate::fmt::Formatter) -&gt; $crate::fmt::Result</code></li></ul></li><li><strong>Hash</strong><ul><li><code>fn hash&lt;__H&gt;(self: &amp;Self, state: &amp; mut __H)</code></li></ul></li><li><strong>PartialEq</strong><ul><li><code>fn eq(self: &amp;Self, other: &amp;Self) -&gt; bool</code></li></ul></li><li><strong>Clone</strong><ul><li><code>fn clone(self: &amp;Self) -&gt; Self</code></li></ul></li><li><strong>Display</strong><ul><li><code>fn fmt(self: &amp;Self, f: &amp; mut fmt::Formatter) -&gt; fmt::Result</code></li></ul></li></ul><h2 id="handl-plugin-ext-refinement-trait-inference-lawannotation" tabindex="-1">handl_plugin_ext_refinement::trait_inference::LawAnnotation <a class="header-anchor" href="#handl-plugin-ext-refinement-trait-inference-lawannotation" aria-label="Permalink to “handl_plugin_ext_refinement::trait_inference::LawAnnotation”">​</a></h2><p><em>Struct</em></p><p>A law-based contract annotation. When a graph is recognized as satisfying a law, the contract inference can use this to simplify or strengthen the inferred contract.</p><p>This is the bridge between the trait inference (which laws a graph satisfies) and the contract inference (what refinement guarantees hold). The Lean4 formalization connects the two via the invariant domain <code>D</code>: law satisfaction implies semantic equivalence, which implies preservation of all <code>D</code>-invariants.</p><p><strong>Fields:</strong></p><ul><li><code>law: Law</code> - The law that is satisfied.</li><li><code>strengthening: String</code> - A human-readable description of how the law strengthens the contract.</li></ul><p><strong>Traits:</strong> Eq</p><p><strong>Trait Implementations:</strong></p><ul><li><strong>PartialEq</strong><ul><li><code>fn eq(self: &amp;Self, other: &amp;Self) -&gt; bool</code></li></ul></li><li><strong>Debug</strong><ul><li><code>fn fmt(self: &amp;Self, f: &amp; mut $crate::fmt::Formatter) -&gt; $crate::fmt::Result</code></li></ul></li><li><strong>Clone</strong><ul><li><code>fn clone(self: &amp;Self) -&gt; Self</code></li></ul></li></ul><h2 id="handl-plugin-ext-refinement-trait-inference-infer-law-annotations" tabindex="-1">handl_plugin_ext_refinement::trait_inference::infer_law_annotations <a class="header-anchor" href="#handl-plugin-ext-refinement-trait-inference-infer-law-annotations" aria-label="Permalink to “handl_plugin_ext_refinement::trait_inference::infer_law_annotations”">​</a></h2><p><em>Function</em></p><p>Infer law-based contract annotations for a <code>Term</code> graph.</p><p>This is the wiring point between the trait inference and the contract inference. When a graph is recognized as satisfying a functor law, the contract inference can use this to simplify or strengthen the inferred contract.</p><p>The annotations describe the semantic consequence of each satisfied law:</p><ul><li><strong>FunctorIdentity</strong>: <code>first(id)</code> is the identity on <code>A × D</code> — the side channel is preserved exactly. This strengthens the <code>LengthEq(input.1, output.1)</code> guarantee that <code>infer_r</code> already derives for <code>First</code>, confirming it is an exact equality (not just length).</li><li><strong>FunctorComposition</strong>: <code>first(comp G H) = comp (first G) (first H)</code> — the guarantee of <code>first(comp G H)</code> is the composition of the guarantees of <code>first G</code> and <code>first H</code>. This confirms the <code>Seq</code> composition rule used by <code>infer_r</code> is sound for <code>First</code>-wrapped graphs.</li><li><strong>CoproductIdentity</strong>: <code>left(id)</code> is the identity on <code>A + D</code> — the right branch passes through unchanged. This confirms the <code>Choice</code> inference rule is sound when the right branch is an identity.</li><li><strong>CoproductComposition</strong>: <code>left(comp G H) = comp (left G) (left H)</code> — the guarantee of <code>left(comp G H)</code> is the composition of the guarantees of <code>left G</code> and <code>left H</code>.</li></ul><div class="language-rust"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">fn</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> infer_law_annotations</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">(</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">scheme</span><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">:</span><span style="--shiki-dark:#0FF;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> &amp;</span><span style="--shiki-dark:#0FF;--shiki-dark-font-weight:bold;--shiki-light:#6F42C1;--shiki-light-font-weight:inherit;">handl_language</span><span style="--shiki-dark:#0FF;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">::</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">Term</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">)</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> -&gt;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> Vec</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">&lt;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">LawAnnotation</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">&gt;</span></span></code></pre></div><h2 id="handl-plugin-ext-refinement-trait-inference-inferred-trait" tabindex="-1">handl_plugin_ext_refinement::trait_inference::inferred_trait <a class="header-anchor" href="#handl-plugin-ext-refinement-trait-inference-inferred-trait" aria-label="Permalink to “handl_plugin_ext_refinement::trait_inference::inferred_trait”">​</a></h2><p><em>Function</em></p><p>The set of laws inferred from a graph&#39;s wiring, by structural recursion.</p><p>This is the Rust mirror of the Lean4 <code>inferred_trait</code> function. It maps a graph to the list of laws it satisfies, by inspecting the wiring structure. No law is declared; the function reads the laws off from the structure.</p><p>The inference is structural:</p><ul><li>A graph using <code>first</code> → functor pattern detected → functor laws.</li><li>A graph using <code>left</code> → coproduct functor pattern detected → coproduct functor laws.</li><li>A graph using neither → no laws.</li></ul><h1 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to “Example”">​</a></h1><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>use handl_language::Term;</span></span>
<span class="line"><span>use handl_plugin_ext_refinement::trait_inference::{inferred_trait, Law};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// first(id) → functor laws.</span></span>
<span class="line"><span>let g = Term::first(Term::arr_native(&quot;id&quot;, vec![]));</span></span>
<span class="line"><span>let laws = inferred_trait(&amp;g);</span></span>
<span class="line"><span>assert!(laws.contains(&amp;Law::FunctorIdentity));</span></span>
<span class="line"><span>assert!(laws.contains(&amp;Law::FunctorComposition));</span></span>
<span class="line"><span>assert!(!laws.contains(&amp;Law::CoproductIdentity));</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// id → no laws.</span></span>
<span class="line"><span>let g = Term::arr_native(&quot;id&quot;, vec![]);</span></span>
<span class="line"><span>assert!(inferred_trait(&amp;g).is_empty());</span></span></code></pre></div><div class="language-rust"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">fn</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> inferred_trait</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">(</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">scheme</span><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">:</span><span style="--shiki-dark:#0FF;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> &amp;</span><span style="--shiki-dark:#0FF;--shiki-dark-font-weight:bold;--shiki-light:#6F42C1;--shiki-light-font-weight:inherit;">handl_language</span><span style="--shiki-dark:#0FF;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">::</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">Term</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">)</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> -&gt;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> Vec</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">&lt;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">Law</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">&gt;</span></span></code></pre></div><h2 id="handl-plugin-ext-refinement-trait-inference-is-identity-td" tabindex="-1">handl_plugin_ext_refinement::trait_inference::is_identity_td <a class="header-anchor" href="#handl-plugin-ext-refinement-trait-inference-is-identity-td" aria-label="Permalink to “handl_plugin_ext_refinement::trait_inference::is_identity_td”">​</a></h2><p><em>Function</em></p><p>Whether a <code>TermData</code> is the identity arrow (<code>op(&quot;id&quot;)</code> with no args).</p><div class="language-rust"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">fn</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> is_identity_td</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">(</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">td</span><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">:</span><span style="--shiki-dark:#0FF;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> &amp;</span><span style="--shiki-dark:#0FF;--shiki-dark-font-weight:bold;--shiki-light:#6F42C1;--shiki-light-font-weight:inherit;">hnl_engine</span><span style="--shiki-dark:#0FF;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">::</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">TermData</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">)</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> -&gt;</span><span style="--shiki-dark:#C5C5C5;--shiki-light:#6F42C1;"> bool</span></span></code></pre></div><h2 id="handl-plugin-ext-refinement-trait-inference-law-strengthening" tabindex="-1">handl_plugin_ext_refinement::trait_inference::law_strengthening <a class="header-anchor" href="#handl-plugin-ext-refinement-trait-inference-law-strengthening" aria-label="Permalink to “handl_plugin_ext_refinement::trait_inference::law_strengthening”">​</a></h2><p><em>Function</em></p><p>The contract-strengthening description for a law.</p><div class="language-rust"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">fn</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> law_strengthening</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">(</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">law</span><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">:</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> Law</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">)</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> -&gt;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> String</span></span></code></pre></div><h2 id="handl-plugin-ext-refinement-trait-inference-law-verified" tabindex="-1">handl_plugin_ext_refinement::trait_inference::law_verified <a class="header-anchor" href="#handl-plugin-ext-refinement-trait-inference-law-verified" aria-label="Permalink to “handl_plugin_ext_refinement::trait_inference::law_verified”">​</a></h2><p><em>Function</em></p><p>Whether a law is verified by CutElim normalization.</p><p>In the Lean4 formalization, <code>LawVerified law</code> is a <code>Prop</code> that holds when both sides of the law normalize to the same canonical form under <code>CutElimStar</code>. The theorem <code>all_functor_laws_verified</code> proves that <strong>all four laws are verified</strong> — with zero <code>sorry</code>.</p><p>In the Rust port, we take this as a proven fact: <code>law_verified</code> always returns <code>true</code>. The structural-pattern check (<code>UsesFirst</code> / <code>UsesLeft</code>) is the only runtime computation needed; the law verification is a theorem, not a runtime check.</p><p>This mirrors the Lean4 design where <code>SatisfiesLaw G law</code> is <code>UsesFirst G ∧ LawVerified law</code> — the <code>LawVerified</code> conjunct is theorem-level (always true), so the runtime work is entirely in the <code>UsesFirst</code> / <code>UsesLeft</code> recognizer.</p><div class="language-rust"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">fn</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> law_verified</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">(</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">_law</span><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">:</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> Law</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">)</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> -&gt;</span><span style="--shiki-dark:#C5C5C5;--shiki-light:#6F42C1;"> bool</span></span></code></pre></div><h2 id="handl-plugin-ext-refinement-trait-inference-satisfies-law" tabindex="-1">handl_plugin_ext_refinement::trait_inference::satisfies_law <a class="header-anchor" href="#handl-plugin-ext-refinement-trait-inference-satisfies-law" aria-label="Permalink to “handl_plugin_ext_refinement::trait_inference::satisfies_law”">​</a></h2><p><em>Function</em></p><p>Whether a <code>Term</code> graph <code>G</code> satisfies <code>law</code>.</p><p>This is the Rust mirror of the Lean4 <code>SatisfiesLaw G law</code> predicate. A graph satisfies a law when:</p><ol><li>G&#39;s wiring exhibits the structural pattern the law applies to (<code>UsesFirst</code> for functor laws, <code>UsesLeft</code> for coproduct-functor laws), AND</li><li>The law is verified by CutElim normalization (<code>LawVerified law</code>).</li></ol><p>Since all four laws are proven verified in the Lean4 formalization (zero <code>sorry</code>), condition (2) always holds. The runtime computation is entirely in the structural-pattern check.</p><h1 id="inference-theorem" tabindex="-1">Inference theorem <a class="header-anchor" href="#inference-theorem" aria-label="Permalink to “Inference theorem”">​</a></h1><p>The Lean4 inference theorems (<code>satisfies_functor_identity</code>, etc.) state: if <code>G</code> uses <code>first</code>, then <code>G</code> satisfies the functor identity and composition laws — <strong>without the law being declared</strong>. This function implements that inference: given a graph and a law, it checks whether the graph&#39;s wiring matches the law&#39;s pattern.</p><h1 id="example-1" tabindex="-1">Example <a class="header-anchor" href="#example-1" aria-label="Permalink to “Example”">​</a></h1><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>use handl_language::Term;</span></span>
<span class="line"><span>use handl_plugin_ext_refinement::trait_inference::{satisfies_law, Law};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// first(id) uses first → satisfies FunctorIdentity.</span></span>
<span class="line"><span>let g = Term::first(Term::arr_native(&quot;id&quot;, vec![]));</span></span>
<span class="line"><span>assert!(satisfies_law(&amp;g, Law::FunctorIdentity));</span></span>
<span class="line"><span>assert!(satisfies_law(&amp;g, Law::FunctorComposition));</span></span>
<span class="line"><span>// first(id) does not use left → does not satisfy CoproductIdentity.</span></span>
<span class="line"><span>assert!(!satisfies_law(&amp;g, Law::CoproductIdentity));</span></span></code></pre></div><div class="language-rust"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">fn</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> satisfies_law</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">(</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">scheme</span><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">:</span><span style="--shiki-dark:#0FF;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> &amp;</span><span style="--shiki-dark:#0FF;--shiki-dark-font-weight:bold;--shiki-light:#6F42C1;--shiki-light-font-weight:inherit;">handl_language</span><span style="--shiki-dark:#0FF;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">::</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">Term</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">,</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;"> law</span><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">:</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> Law</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">)</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> -&gt;</span><span style="--shiki-dark:#C5C5C5;--shiki-light:#6F42C1;"> bool</span></span></code></pre></div><h2 id="handl-plugin-ext-refinement-trait-inference-uses-first" tabindex="-1">handl_plugin_ext_refinement::trait_inference::uses_first <a class="header-anchor" href="#handl-plugin-ext-refinement-trait-inference-uses-first" aria-label="Permalink to “handl_plugin_ext_refinement::trait_inference::uses_first”">​</a></h2><p><em>Function</em></p><p>Whether a <code>Term</code> graph <em>uses <code>first</code></em> — i.e. <code>Term::First</code> appears anywhere in its wiring.</p><p>This is the Rust mirror of the Lean4 <code>UsesFirst</code> inductive predicate. A graph uses <code>first</code> if:</p><ul><li>It is a <code>Term::First { .. }</code> node (the <code>here</code> case), OR</li><li>It is a <code>Term::Seq { fst, snd }</code> and either <code>fst</code> or <code>snd</code> uses <code>first</code> (the <code>leftComp</code> / <code>rightComp</code> cases), OR</li><li>It is a <code>Term::Loop { body }</code> and <code>body</code> uses <code>first</code>, OR</li><li>It is a <code>Term::Choice { l, r }</code> and either branch uses <code>first</code>, OR</li><li>It is a <code>Term::App { callee, args }</code> and the callee or any arg uses <code>first</code>.</li></ul><p><code>Term::Arr</code> nodes never use <code>first</code> (they are base arrows).</p><h1 id="example-2" tabindex="-1">Example <a class="header-anchor" href="#example-2" aria-label="Permalink to “Example”">​</a></h1><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>use handl_language::Term;</span></span>
<span class="line"><span>use handl_plugin_ext_refinement::trait_inference::uses_first;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// first(id) — uses first directly.</span></span>
<span class="line"><span>let g = Term::first(Term::arr_native(&quot;id&quot;, vec![]));</span></span>
<span class="line"><span>assert!(uses_first(&amp;g));</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// comp(first(id), id) — uses first in the left component.</span></span>
<span class="line"><span>let g = Term::seq(</span></span>
<span class="line"><span>    Term::first(Term::arr_native(&quot;id&quot;, vec![])),</span></span>
<span class="line"><span>    Term::arr_native(&quot;id&quot;, vec![]),</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span>assert!(uses_first(&amp;g));</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// id — does not use first.</span></span>
<span class="line"><span>let g = Term::arr_native(&quot;id&quot;, vec![]);</span></span>
<span class="line"><span>assert!(!uses_first(&amp;g));</span></span></code></pre></div><div class="language-rust"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">fn</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> uses_first</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">(</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">scheme</span><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">:</span><span style="--shiki-dark:#0FF;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> &amp;</span><span style="--shiki-dark:#0FF;--shiki-dark-font-weight:bold;--shiki-light:#6F42C1;--shiki-light-font-weight:inherit;">handl_language</span><span style="--shiki-dark:#0FF;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">::</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">Term</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">)</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> -&gt;</span><span style="--shiki-dark:#C5C5C5;--shiki-light:#6F42C1;"> bool</span></span></code></pre></div><h2 id="handl-plugin-ext-refinement-trait-inference-uses-first-td" tabindex="-1">handl_plugin_ext_refinement::trait_inference::uses_first_td <a class="header-anchor" href="#handl-plugin-ext-refinement-trait-inference-uses-first-td" aria-label="Permalink to “handl_plugin_ext_refinement::trait_inference::uses_first_td”">​</a></h2><p><em>Function</em></p><p>Data-driven counterpart of [<code>uses_first</code>], operating on [<code>TermData</code>].</p><div class="language-rust"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">fn</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> uses_first_td</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">(</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">td</span><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">:</span><span style="--shiki-dark:#0FF;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> &amp;</span><span style="--shiki-dark:#0FF;--shiki-dark-font-weight:bold;--shiki-light:#6F42C1;--shiki-light-font-weight:inherit;">hnl_engine</span><span style="--shiki-dark:#0FF;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">::</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">TermData</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">)</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> -&gt;</span><span style="--shiki-dark:#C5C5C5;--shiki-light:#6F42C1;"> bool</span></span></code></pre></div><h2 id="handl-plugin-ext-refinement-trait-inference-uses-left" tabindex="-1">handl_plugin_ext_refinement::trait_inference::uses_left <a class="header-anchor" href="#handl-plugin-ext-refinement-trait-inference-uses-left" aria-label="Permalink to “handl_plugin_ext_refinement::trait_inference::uses_left”">​</a></h2><p><em>Function</em></p><p>Whether a <code>Term</code> graph <em>uses <code>left</code></em> — i.e. the coproduct-functor combinator appears anywhere in its wiring.</p><p>In the Lean4 formalization, <code>left F</code> is a dedicated graph constructor that routes <code>Left</code> through <code>F</code> and <code>Right</code> through the identity. In the Rust <code>Term</code> IR, the coproduct functor is represented as <code>Term::Choice { l: F, r: id }</code> — the left branch is the active sub-graph, and the right branch is the pass-through identity.</p><p>This recognizer checks for <code>Choice</code> nodes where the left branch is non-trivial (not just an identity) — this distinguishes a genuine <code>left(F)</code> (coproduct functor) from a general <code>choice(G, H)</code> (which may be a conditional, not a functor application). The right branch being an identity (<code>op == &quot;id&quot;</code>) is the hallmark of <code>left</code>.</p><p>This is the Rust mirror of the Lean4 <code>UsesLeft</code> inductive predicate.</p><h1 id="example-3" tabindex="-1">Example <a class="header-anchor" href="#example-3" aria-label="Permalink to “Example”">​</a></h1><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>use handl_language::Term;</span></span>
<span class="line"><span>use handl_plugin_ext_refinement::trait_inference::uses_left;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// left(id) = choice(id, id) — uses left (coproduct functor).</span></span>
<span class="line"><span>let g = Term::choice(</span></span>
<span class="line"><span>    Term::arr_native(&quot;id&quot;, vec![]),</span></span>
<span class="line"><span>    Term::arr_native(&quot;id&quot;, vec![]),</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span>assert!(uses_left(&amp;g));</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// id — does not use left.</span></span>
<span class="line"><span>let g = Term::arr_native(&quot;id&quot;, vec![]);</span></span>
<span class="line"><span>assert!(!uses_left(&amp;g));</span></span></code></pre></div><div class="language-rust"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">fn</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> uses_left</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">(</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">scheme</span><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">:</span><span style="--shiki-dark:#0FF;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> &amp;</span><span style="--shiki-dark:#0FF;--shiki-dark-font-weight:bold;--shiki-light:#6F42C1;--shiki-light-font-weight:inherit;">handl_language</span><span style="--shiki-dark:#0FF;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">::</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">Term</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">)</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> -&gt;</span><span style="--shiki-dark:#C5C5C5;--shiki-light:#6F42C1;"> bool</span></span></code></pre></div><h2 id="handl-plugin-ext-refinement-trait-inference-uses-left-td" tabindex="-1">handl_plugin_ext_refinement::trait_inference::uses_left_td <a class="header-anchor" href="#handl-plugin-ext-refinement-trait-inference-uses-left-td" aria-label="Permalink to “handl_plugin_ext_refinement::trait_inference::uses_left_td”">​</a></h2><p><em>Function</em></p><p>Data-driven counterpart of [<code>uses_left</code>], operating on [<code>TermData</code>].</p><div class="language-rust"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">fn</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> uses_left_td</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">(</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">td</span><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">:</span><span style="--shiki-dark:#0FF;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> &amp;</span><span style="--shiki-dark:#0FF;--shiki-dark-font-weight:bold;--shiki-light:#6F42C1;--shiki-light-font-weight:inherit;">hnl_engine</span><span style="--shiki-dark:#0FF;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">::</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">TermData</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">)</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> -&gt;</span><span style="--shiki-dark:#C5C5C5;--shiki-light:#6F42C1;"> bool</span></span></code></pre></div>`,100)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};